//! Auto-generated C++ code generation for Polyglot Lab.

use anyhow::Result;
use lab_node_sdk::GraphSpec;
use std::collections::{HashMap, HashSet};

/// Generates `CMakeLists.txt` content.
pub fn generate_cmake_lists(project_name: &str) -> String {
    let safe_name = crate::codegen::sanitize_ident(project_name);
    format!(
        r#"cmake_minimum_required(VERSION 3.20)
project({safe_name} CXX)

set(CMAKE_CXX_STANDARD 20)
set(CMAKE_CXX_STANDARD_REQUIRED ON)

include_directories(include)

add_executable({safe_name} src/main.cpp)
"#
    )
}

/// Generates `include/nodes.hpp` with self-contained implementations of atomic nodes.
pub fn generate_nodes_hpp(used_kinds: &HashSet<&str>) -> String {
    let mut code = String::from(
        r#"// Code generated by Polyglot Lab. DO NOT EDIT.
#pragma once

#include <iostream>
#include <string>
#include <fstream>
#include <sstream>
#include <chrono>
#include <thread>
#include <algorithm>
#include <cctype>
#include <stdexcept>

namespace nodes {

"#,
    );

    if used_kinds.contains("fs_read") {
        code.push_str(
            r#"inline std::string fs_read(const std::string& path) {
    std::cout << "   Reading file: " << path << "\n";
    std::ifstream file(path);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file: " + path);
    }
    std::stringstream buffer;
    buffer << file.rdbuf();
    return buffer.str();
}

"#,
        );
    }

    if used_kinds.contains("fs_write") {
        code.push_str(
            r#"inline int fs_write(const std::string& path, const std::string& content) {
    std::cout << "   Writing to file: " << path << "\n";
    std::ofstream file(path);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file for writing: " + path);
    }
    file << content;
    return static_cast<int>(content.size());
}

"#,
        );
    }

    if used_kinds.contains("log_output") {
        code.push_str(
            r#"template <typename T>
inline void log_output(const T& text) {
    std::cout << "   Log Output: " << text << "\n";
}

"#,
        );
    }

    if used_kinds.contains("text_clean") {
        code.push_str(
            r#"inline std::string text_clean(const std::string& text, bool trim = true, bool collapse = false, bool to_lower = false, bool to_upper = false) {
    if (to_lower && to_upper) {
        throw std::invalid_argument("'to_lower' and 'to_upper' cannot both be true");
    }
    std::string res = text;
    if (trim) {
        size_t start = res.find_first_not_of(" \t\n\r");
        size_t end = res.find_last_not_of(" \t\n\r");
        res = (start == std::string::npos) ? "" : res.substr(start, end - start + 1);
    }
    if (to_lower) {
        std::transform(res.begin(), res.end(), res.begin(), [](unsigned char c) { return std::tolower(c); });
    }
    if (to_upper) {
        std::transform(res.begin(), res.end(), res.begin(), [](unsigned char c) { return std::toupper(c); });
    }
    return res;
}

"#,
        );
    }

    if used_kinds.contains("delay") {
        code.push_str(
            r#"inline void delay(const std::string& duration_str) {
    std::cout << "   Sleeping for " << duration_str << "\n";
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
}

"#,
        );
    }

    if used_kinds.contains("string_to_path") {
        code.push_str(
            r#"inline std::string string_to_path(const std::string& raw) {
    if (raw.empty()) {
        throw std::invalid_argument("Path cannot be empty");
    }
    return raw;
}

"#,
        );
    }

    if used_kinds.contains("http_get") {
        code.push_str(
            r#"inline std::string http_get(const std::string& url) {
    std::cout << "   HTTP GET: " << url << "\n";
    return std::string("{\"status\":\"ok\",\"simulated_url\":\"") + url + "\"}";
}

"#,
        );
    }

    if used_kinds.contains("json_parse") {
        code.push_str(
            r#"inline std::string json_parse(const std::string& json_str, const std::string& path = "") {
    std::cout << "   Parsing JSON: " << json_str << " (path: " << path << ")\n";
    return json_str;
}

"#,
        );
    }

    if used_kinds.contains("json_to_string") {
        code.push_str(
            r#"inline std::string json_to_string(const std::string& raw) {
    return raw;
}

"#,
        );
    }

    if used_kinds.contains("json_to_bool") {
        code.push_str(
            r#"inline bool json_to_bool(const std::string& raw) {
    return raw == "true" || raw == "1";
}

"#,
        );
    }

    code.push_str("} // namespace nodes\n");
    code
}

fn cpp_string_literal(value: &str) -> String {
    format!("{value:?}")
}

/// Generates C++ code statement for a single node.
pub fn generate_cpp_node_call(
    node: &lab_node_sdk::NodeInstance,
    graph: &GraphSpec,
    indent: &str,
) -> String {
    let mut out = format!("{indent}// 🚀 Node: '{}' ({})\n", node.id, node.kind);
    let id_ident = crate::codegen::sanitize_ident(&node.id);

    let mut in_edges: HashMap<&str, (&str, &str)> = HashMap::new();
    for edge in &graph.edges {
        if edge.to.node == node.id {
            in_edges.insert(&edge.to.port, (&edge.from.node, &edge.from.port));
        }
    }

    match node.kind.as_str() {
        "fs_read" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let p = node
                    .config
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                cpp_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}auto {id_ident}_content = nodes::fs_read({path_expr});\n"
            ));
        }
        "fs_write" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let p = node
                    .config
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                cpp_string_literal(p)
            };
            let content_expr = if let Some(&(src, sport)) = in_edges.get("content") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let c = node
                    .config
                    .get("content")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                cpp_string_literal(c)
            };
            out.push_str(&format!("{indent}auto {id_ident}_bytes_written = nodes::fs_write({path_expr}, {content_expr});\n"));
        }
        "log_output" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let t = node
                    .config
                    .get("text")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                cpp_string_literal(t)
            };
            out.push_str(&format!("{indent}nodes::log_output({text_expr});\n"));
        }
        "text_clean" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let t = node
                    .config
                    .get("text")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                cpp_string_literal(t)
            };
            let trim = if node
                .config
                .get("trim")
                .and_then(|v| v.as_bool())
                .unwrap_or(true)
            {
                "true"
            } else {
                "false"
            };
            let collapse = if node
                .config
                .get("collapse")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                "true"
            } else {
                "false"
            };
            let to_lower = if node
                .config
                .get("to_lower")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                "true"
            } else {
                "false"
            };
            let to_upper = if node
                .config
                .get("to_upper")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                "true"
            } else {
                "false"
            };
            out.push_str(&format!("{indent}auto {id_ident}_cleaned = nodes::text_clean({text_expr}, {trim}, {collapse}, {to_lower}, {to_upper});\n"));
        }
        "delay" => {
            let dur_expr = if let Some(&(src, sport)) = in_edges.get("duration") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let d = node
                    .config
                    .get("duration")
                    .and_then(|v| v.as_str())
                    .unwrap_or("0ms");
                cpp_string_literal(d)
            };
            out.push_str(&format!("{indent}nodes::delay({dur_expr});\n"));
        }
        "string_to_path" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let p = node
                    .config
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                cpp_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}auto {id_ident}_path = nodes::string_to_path({path_expr});\n"
            ));
        }
        "http_get" => {
            let url_expr = if let Some(&(src, sport)) = in_edges.get("url") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let u = node
                    .config
                    .get("url")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                cpp_string_literal(u)
            };
            out.push_str(&format!(
                "{indent}auto {id_ident}_body = nodes::http_get({url_expr});\n"
            ));
        }
        "json_parse" => {
            let json_expr = if let Some(&(src, sport)) = in_edges.get("json_str") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let j = node
                    .config
                    .get("json_str")
                    .and_then(|v| v.as_str())
                    .unwrap_or("{}");
                cpp_string_literal(j)
            };
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else if let Some(p) = node.config.get("path").and_then(|v| v.as_str()) {
                cpp_string_literal(p)
            } else {
                "\"\"".to_string()
            };
            out.push_str(&format!(
                "{indent}auto {id_ident}_value = nodes::json_parse({json_expr}, {path_expr});\n"
            ));
        }
        "json_to_string" => {
            let val_expr = if let Some(&(src, sport)) = in_edges.get("value") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                "\"\"".to_string()
            };
            out.push_str(&format!(
                "{indent}auto {id_ident}_text = nodes::json_to_string({val_expr});\n"
            ));
        }
        "json_to_bool" => {
            let val_expr = if let Some(&(src, sport)) = in_edges.get("value") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                "\"false\"".to_string()
            };
            out.push_str(&format!(
                "{indent}auto {id_ident}_value = nodes::json_to_bool({val_expr});\n"
            ));
        }
        _ => {}
    }

    out
}

/// Generates `src/main.cpp` with topological execution, branching if/else, and error handling.
pub fn generate_main_cpp(graph: &GraphSpec, topo_order: &[String]) -> Result<String> {
    let node_map: HashMap<&str, &lab_node_sdk::NodeInstance> =
        graph.nodes.iter().map(|n| (n.id.as_str(), n)).collect();

    let conditions: Vec<&lab_node_sdk::NodeInstance> = graph
        .nodes
        .iter()
        .filter(|n| n.kind == "condition")
        .collect();

    let mut body = String::new();

    if conditions.is_empty() {
        for id in topo_order {
            if let Some(node) = node_map.get(id.as_str()) {
                body.push_str(&generate_cpp_node_call(node, graph, "    "));
            }
        }
    } else {
        let cond = conditions[0];
        let true_target = cond
            .config
            .get("true_branch")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let false_target = cond
            .config
            .get("false_branch")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        let reach_true = crate::codegen::reachable_from(true_target, graph);
        let reach_false = crate::codegen::reachable_from(false_target, graph);

        let true_exclusive: HashSet<_> = reach_true.difference(&reach_false).cloned().collect();
        let false_exclusive: HashSet<_> = reach_false.difference(&reach_true).cloned().collect();

        // 1. Nodes before condition
        let cond_idx = topo_order.iter().position(|id| id == &cond.id).unwrap_or(0);
        for id in &topo_order[..cond_idx] {
            if let Some(node) = node_map.get(id.as_str()) {
                body.push_str(&generate_cpp_node_call(node, graph, "    "));
            }
        }

        // 2. Condition evaluation
        let cond_val_expr = if let Some(edge) = graph
            .edges
            .iter()
            .find(|e| e.to.node == cond.id && e.to.port == "value")
        {
            format!(
                "{}_{}",
                crate::codegen::sanitize_ident(&edge.from.node),
                crate::codegen::sanitize_ident(&edge.from.port)
            )
        } else {
            let b = cond
                .config
                .get("value")
                .and_then(|v| v.as_bool())
                .unwrap_or(false);
            format!("{b}")
        };

        body.push_str(&format!(
            "    // 🌿 Branching Condition: '{}'\n    if ({cond_val_expr}) {{\n",
            cond.id
        ));

        // True branch nodes in topological order
        for id in topo_order {
            if true_exclusive.contains(id) {
                if let Some(node) = node_map.get(id.as_str()) {
                    body.push_str(&generate_cpp_node_call(node, graph, "        "));
                }
            }
        }

        body.push_str("    } else {\n");

        // False branch nodes in topological order
        for id in topo_order {
            if false_exclusive.contains(id) {
                if let Some(node) = node_map.get(id.as_str()) {
                    body.push_str(&generate_cpp_node_call(node, graph, "        "));
                }
            }
        }

        body.push_str("    }\n\n");
    }

    let code = format!(
        r#"// Code generated by Polyglot Lab. DO NOT EDIT.
#include <iostream>
#include "nodes.hpp"

int main() {{
    std::cout << "🚀 Starting exported C++ application...\n";

{body}
    std::cout << "✅ Application finished successfully!\n";
    return 0;
}}
"#
    );

    Ok(code)
}
